refentry.refsect1:
&reftitle.description;
public stringnullYaf_Controller_Abstract::getInvokeArg stringname
根据名称返回当前动作的单个调用参数。调用参数通过 Yaf_Controller_Abstract::forward 传递给动作。

&reftitle.parameters;


  name


    要获取的调用参数的名称。

  &reftitle.examples;

   Yaf_Controller_Abstract::getInvokeArg 示例


<?php
class UserController extends Yaf_Controller_Abstract
{
    public function indexAction() {
        // 转发到本控制器的 profile 动作，
        // 并携带调用参数
        $this->forward("profile", array("name" => "laruence"));
        return false; // 结束当前流程
    }

    public function profileAction() {
        // 按名称获取单个调用参数
        var_dump($this->getInvokeArg("name"));
        var_dump($this->getInvokeArg("missing"));
    }
}
?>


   &example.outputs.similar;


string(8) "laruence"
